  const weekStartMs=(()=>{const d=new Date(now);d.setHours(0,0,0,0);const offset=store.settings.weekStart==='Sunday'?d.getDay():(d.getDay()+6)%7;d.setDate(d.getDate()-offset);return d.getTime();})();
  const listTasks=store.tasks.filter(t=>t.kind!=='project');
