let lastGroup:string|undefined;const rows:React.ReactNode[]=[];visibleTaskList.forEach(task=>{const g=groupOf(task);if(g&&g!==lastGroup){rows.push(<tr key={`group-${g}`} className="task-group-row"><td colSpan={8}><span className={`task-group-label group-${g.toLowerCase().replace(/\s+/g,'-')}`}>{g}</span><span className="task-group-count">{groupCounts[g]}</span></td></tr>);lastGroup=g;}rows.push(renderRow(task));});
