function inheritedColor(parents:string|string[]|undefined,tasks:Task[]):string|undefined { const queue=[...(Array.isArray(parents)?parents:parents?[parents]:[])]; const seen=new Set<string>(); while(queue.length){ const id=queue.shift()!; if(seen.has(id)) continue; seen.add(id); const current=tasks.find(t=>t.id===id); if(!current) continue; if(current.projectColor) return current.projectColor; queue.push(...parentIdsOf(current)); } return undefined; }
