function categoryClass(category?: string,color?:string) { const known:Record<string,string>={Work:'work',Personal:'personal',Admin:'admin',Learning:'learning',Health:'health'};return color?.startsWith('#')?'category-custom':`category-${color??known[category??'Work']??'work'}`; }
function categoryStyle(color?:string):CSSProperties|undefined { return color?.startsWith('#')?{'--category-color':color} as CSSProperties:undefined; }
function wouldCreateDependencyCycle(tasks:Task[],taskId:string,prerequisiteId:string) { const seen=new Set<string>(); const visit=(id:string):boolean=>{if(id===taskId)return true;if(seen.has(id))return false;seen.add(id);return (tasks.find(t=>t.id===id)?.dependencies??[]).some(visit);};return visit(prerequisiteId); }
function MindTreeNode({task,store,selectedId,onSelect,onAddChild,showCompleted,depth=0}:{task:Task;store:Store;selectedId?:string;onSelect:(id:string)=>void;onAddChild:(id:string)=>void;showCompleted:boolean;depth?:number}){const [open,setOpen]=useState(true);const children=store.tasks.filter(t=>parentIdsOf(t).includes(task.id)&&(showCompleted||!t.done));return <div className="mindtree-branch"><div className={`mindtree-row ${selectedId===task.id?'active':''} ${task.done?'completed':''}`} style={{paddingLeft:10+depth*13}}><button className="mindtree-expand" onClick={()=>setOpen(v=>!v)}>{children.length?(open?<ChevronDown size={13}/>:<ChevronRight size={13}/>):<span/>}</button><button className="mindtree-select" onClick={()=>onSelect(task.id)}><span className={`category-icon ${categoryClass(task.category,taskColor(task,store.tasks))}`} style={categoryStyle(taskColor(task,store.tasks))}>{task.kind==='project'?<FolderKanban size={13}/>:<span/>}</span><span>{task.name}</span></button><button className="mindtree-add" onClick={()=>onAddChild(task.id)} title="Add subtask"><Plus size={13}/></button></div>{open&&children.map(child=><MindTreeNode key={child.id} task={child} store={store} selectedId={selectedId} onSelect={onSelect} onAddChild={onAddChild} showCompleted={showCompleted} depth={depth+1}/>)}</div>}
function CompletedTasksTable({tasks,store,now,onReopen,onSelect}:{tasks:Task[];store:Store;now:number;onReopen:(task:Task)=>void;onSelect:(id:string)=>void}){return <section className="completed-tasks-panel"><div className="completed-panel-head"><div><h2>Completed tasks</h2><p>Closed tasks and subtasks</p></div><span>{tasks.length}</span></div><div className="completed-table-wrap"><table><thead><tr><th>TASK</th><th>PARENT / TYPE</th><th>TIME TRACKED</th><th></th></tr></thead><tbody>{tasks.map(task=>{const parentNames=parentIdsOf(task).map(id=>store.tasks.find(t=>t.id===id)?.name).filter(Boolean).join(', ');return <tr key={task.id}><td><button className="completed-task-name" onClick={()=>onSelect(task.id)}><span className={`category-icon ${categoryClass(task.category,taskColor(task,store.tasks))}`} style={categoryStyle(taskColor(task,store.tasks))}>{task.kind==='project'?<FolderKanban size={13}/>:<span/>}</span><span>{task.name}</span></button></td><td>{parentNames||(task.kind==='project'?'Project':'Independent task')}</td><td className="completed-duration">{fmt(task.kind==='project'?totalTaskMs(task,store,now):elapsed(task.entries,now))}</td><td><button className="mark-complete-button reopen" onClick={()=>onReopen(task)}>Reopen</button></td></tr>})}</tbody></table></div></section>}
function taskNodeWidth(task:Task) { return task.mapWidth??230; }
function taskNodeHeight(task:Task) { if(task.mapHeight)return task.mapHeight; const description=task.description??""; const lines=description.split("\n").reduce((n,line)=>n+Math.max(1,Math.ceil(line.length/36)),0); return Math.max(104,43+Math.max(24,lines*13+10)+31); }
