 function point(e:ReactPointerEvent){const rect=canvasRef.current!.getBoundingClientRect();return{x:(e.clientX-rect.left+canvasRef.current!.scrollLeft)/zoom,y:(e.clientY-rect.top+canvasRef.current!.scrollTop-52)/zoom};}
